TEST(CeltPlc, MatchesReference) {
    for (size_t s = 0; s < kSequences.size(); ++s) {
        const Sequence& seq = kSequences[s];
        player::audio::opus::CeltFrameDecoder decoder;
        decoder.init(seq.channels);
        for (size_t f = 0; f < seq.frames.size(); ++f) {
            const FrameCase& frame = seq.frames[f];
            std::vector<float> pcm(static_cast<size_t>(120 << seq.lm) * seq.channels);
            if (frame.lost) {
                decoder.decodeLost(seq.lm, pcm.data());
            } else {
                player::audio::opus::RangeDecoder dec(frame.packet.data(), frame.packet.size());
                decoder.decode(dec, seq.lm, seq.channels, pcm.data());
            }
            ASSERT_EQ(pcm.size(), frame.pcm.size());
            for (size_t i = 0; i < pcm.size(); ++i) {
                EXPECT_NEAR(pcm[i], frame.pcm[i], 1e-6f) << "seq " << s << " frame " << f << " sample " << i;
            }
        }
    }
}
